function readCount(value, label) {
  const n = typeof value === "string" && /^\d+$/.test(value) ? Number(value) : value;
  if (!Number.isSafeInteger(n) || n < 0)
    throw new Error("WordPress did not provide a valid " + label);
  return n;
}

function csvText(value) {
  // Keep spreadsheet control prefixes inert and escape CSV separators and quotes in one text cell.
  const guarded = /^[\t\r\n\x00]|^[\s\u200b\ufeff]*[=+\-@＝＋－＠]/u.test(value)
    ? "'" + value
    : value;
  return '"' + guarded.replaceAll('"', '""') + '"';
}

function pageOfPosts({ posts, pagination, previous, page, pageSize, maxBytes, header }) {
  const total = readCount(pagination?.total, "X-WP-Total");
  const pages = readCount(pagination?.totalPages, "X-WP-TotalPages");
  const ids = new Set(previous?.ids ?? []);
  if (
    !Array.isArray(posts) ||
    pages !== Math.ceil(total / pageSize) ||
    page > Math.max(pages, 1) ||
    (previous && (previous.total !== total || previous.pages !== pages)) ||
    ids.size !== (page - 1) * pageSize ||
    posts.length !== Math.min(pageSize, total - ids.size)
  ) {
    throw new Error("WordPress pagination changed or returned an incomplete post collection");
  }

  const rows = [];
  for (const post of posts) {
    if (
      !Number.isSafeInteger(post?.id) ||
      post.id <= 0 ||
      ids.has(post.id) ||
      post.status !== "publish" ||
      post.type !== "post" ||
      typeof post.title?.rendered !== "string" ||
      typeof post.link !== "string" ||
      !post.link ||
      typeof post.content?.rendered !== "string"
    ) {
      throw new Error("WordPress returned a duplicate or invalid published post");
    }
    ids.add(post.id);
    rows.push(
      post.id +
        "," +
        [post.title.rendered, post.link, post.content.rendered].map(csvText).join(",") +
        "\r\n",
    );
  }
  const content = (previous ? "" : header) + rows.join("");
  const byteCount = (previous?.byteCount ?? 0) + new TextEncoder().encode(content).length;
  if (byteCount > maxBytes)
    throw new Error("The complete CSV exceeds this workflow’s upload size limit");
  return { ids: [...ids], total, pages, byteCount, text: (previous?.text ?? "") + content };
}

const header = "id,title,link,content\r\n";

let state;
const pages = $input.all();
for (const [index, item] of pages.entries()) {
  const response = item.json;
  if (response.statusCode !== 200) throw new Error("WordPress did not return HTTP 200");
  const headers = response.headers;
  const pagination = { total: headers?.["x-wp-total"], totalPages: headers?.["x-wp-totalpages"] };
  state = pageOfPosts({
    posts: response.body,
    pagination,
    previous: state,
    page: index + 1,
    pageSize: 10,
    maxBytes: Number.MAX_SAFE_INTEGER,
    header,
  });
}
if (!state || pages.length !== Math.max(1, state.pages) || state.ids.length !== state.total) {
  throw new Error("WordPress did not return the complete post collection");
}
if (!state.total) return [];
const bytes = Buffer.from(state.text, "utf8");
return [{ json: { base64: bytes.toString("base64"), rows: state.total, byteCount: bytes.length } }];

function driveReceipt(file, { folder, name, byteCount }) {
  if (
    !file?.id ||
    file.name !== name ||
    file.mimeType !== "text/csv" ||
    String(file.size) !== String(byteCount) ||
    !Array.isArray(file.parents) ||
    !file.parents.length ||
    (folder !== "root" && !file.parents.includes(folder))
  ) {
    throw new Error(
      "Google Drive did not confirm the complete CSV in the selected folder. Review Drive before retrying.",
    );
  }
  return { fileId: file.id, sizeBytes: byteCount };
}

const { rows, byteCount } = $("Build the complete CSV").first().json;
const folder = $("Upload one CSV to Google Drive").params.folderId.value;
const receipt = driveReceipt($json, { folder, name: "Wordpress-Posts.csv", byteCount });
return { json: { rows, ...receipt } };
